function validate(input) {
  const [content] = input;
  if (typeof content !== 'string' || content.length > 10000) return 'content must be text of at most 10,000 characters.';
  if (!/^[\x20-\x7e\n]*$/.test(content)) return 'Use printable ASCII characters and line breaks only.';
  for (const line of content.split('\n')) if (/^\s|\s$/.test(line)) return 'Lines must not start or end with spaces.';
  return null;
}

