function validPhoneNumbers(content) {
  const pattern = /^(\(\d{3}\) |\d{3}-)\d{3}-\d{4}$/;
  const lines = content.split('\n');
  const valid = [];
  for (const line of lines) {
    if (pattern.test(line)) {
      valid.push(line);
    }
  }
  return valid.join('\n');
}

