function validPhoneNumbers(content) {
  // Turn every digit into 9 (a non-digit never becomes 9) and compare the shape with the two allowed ones.
  const out = [];
  let line = '';
  for (const ch of content + '\n') {
    if (ch !== '\n') { line += ch; continue; }
    let shape = '';
    for (const c of line) shape += '0123456789'.includes(c) ? '9' : c;
    if (shape === '(999) 999-9999' || shape === '999-999-9999') out.push(line);
    line = '';
  }
  return out.join('\n');
}

