function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const digits = (n) => Array.from({ length: n }, () => pick(10)).join('');
  const noise = '0123456789 -()ax.+';
  const valid = () => (rand() < 0.5 ? `(${digits(3)}) ` : `${digits(3)}-`) + `${digits(3)}-${digits(4)}`;
  const broken = () => {
    const r = rand();
    if (r < 0.15) return `${digits(3)} ${digits(3)} ${digits(4)}`;
    if (r < 0.25) return `(${digits(3)})${digits(3)}-${digits(4)}`;
    if (r < 0.32) return `(${digits(3)})-${digits(3)}-${digits(4)}`;
    if (r < 0.38) return digits(10);
    if (r < 0.42) return '';
    // Change one character of a valid number: delete it, insert one, or replace it.
    const chars = valid().split(''), at = pick(chars.length), kind = pick(3);
    if (kind === 0) chars.splice(at, 1);
    else if (kind === 1) chars.splice(at, 0, noise[pick(noise.length)]);
    else chars[at] = noise[pick(noise.length)];
    return chars.join('').trim();
  };
  const count = size === 'small' ? pick(7) : 200 + pick(301);
  const lines = [];
  for (let i = 0; i < count; i++) lines.push(rand() < 0.45 ? valid() : broken());
  if (count > 0 && size === 'small' && rand() < 0.3) lines.push(lines[pick(lines.length)]);
  let content = lines.join('\n');
  if (lines.length > 0 && rand() < 0.5) content += '\n';
  return [content];
}
